{"file_path":"/Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/set-3/run-2/suite-a/tests/TC-01-login.spec.ts","content":"// TC-01: Login with a valid and an invalid password (test-cases/TC-01-login.md)
import { test, expect } from '../fixtures';
import { LoginPage } from '../pages/login-page';
import { newCustomer, registerCustomer } from '../helpers/customer';

test('TC-01: login with a valid and an invalid password', async ({ page }) => {
  const customer = newCustomer('TC01');
  const login = new LoginPage(page);
  await registerCustomer(page, customer);

  await test.step('1. Open the login page /#/login', async () => {
    await login.goto();
    await expect(login.heading).toHaveText('Login');
    await expect(login.emailField).toBeVisible();
    await expect(login.passwordField).toBeVisible();
    await expect(login.loginButton).toBeVisible();
  });

  await test.step('2. Log in with the email and the wrong password', async () => {
    await login.login(customer.email, customer.wrongPassword);
    await login.expectNotification('Invalid email or password.');
    await login.expectOnLoginPage();
  });

  await test.step('3. Open the account menu: it shows Login and not the email', async () => {
    await login.openAccountMenu();
    await expect(login.menu.getByRole('menuitem', { name: 'Login', exact: true })).toBeVisible();
    await expect(login.menu).not.toContainText(customer.email);
    await login.closeMenu();
  });

  await test.step('4. Log in with the email and the correct password', async () => {
    await login.login(customer.email, customer.password);
    await expect(page).toHaveURL(/#\/search/);
  });

  await test.step('5. Open the account menu: it shows the email and Logout', async () => {
    await login.openAccountMenu();
    await expect(login.menu).toContainText(customer.email);
    await expect(login.menu.getByRole('menuitem', { name: 'Logout', exact: true })).toBeVisible();
  });
});
"}

{"file_path":"/Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/set-3/run-2/suite-a/tests/TC-02-add-to-basket.spec.ts","content":"// TC-02: Add a product to the basket (test-cases/TC-02-add-to-basket.md)
