{"file_path":"/Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/set-3/run-2/suite-a/tests/TC-03-basket-quantity-and-remove.spec.ts","content":"// TC-03: Change the quantity and remove a product in the basket (test-cases/TC-03-basket-quantity-and-remove.md)
import { test, expect } from '../fixtures';
import { BasketPage } from '../pages/basket-page';
import { SearchPage } from '../pages/search-page';
import { PRODUCTS } from '../helpers/data';
import { newCustomer, registerAndLogin } from '../helpers/customer';

test('TC-03: change the quantity and remove a product in the basket', async ({ page }) => {
  const productA = PRODUCTS.raspberryJuice;
  const productB = PRODUCTS.eggfruitJuice;
  const search = new SearchPage(page);
  const basket = new BasketPage(page);
  await registerAndLogin(page, newCustomer('TC03'));

  // Precondition: product A and product B, one of each, in the basket.
  await search.goto();
  await search.addToBasket(productA.name);
  await search.expectNotification(`Placed ${productA.name} into basket.`);
  await search.addToBasket(productB.name);
  await search.expectNotification(`Placed ${productB.name} into basket.`);

  await test.step('1. Open the basket: A and B with quantity 1, total 13.98¤, counter 2', async () => {
    await basket.goto();
    await basket.expectRow(productA.name, 1);
    await basket.expectRow(productB.name, 1);
    await basket.expectTotal('13.98¤');
    await search.expectBasketCounter(2);
  });

  await test.step('2. Click plus on A: A has quantity 2, total 18.97¤, counter 3', async () => {
    await basket.plusButton(productA.name).click();
    await basket.expectRow(productA.name, 2);
    await basket.expectTotal('18.97¤');
    await search.expectBasketCounter(3);
  });

  await test.step('3. Click minus on A: A has quantity 1, total 13.98¤, counter 2', async () => {
    await basket.minusButton(productA.name).click();
    await basket.expectRow(productA.name, 1);
    await basket.expectTotal('13.98¤');
    await search.expectBasketCounter(2);
  });

  await test.step('4. Click minus on A again: A keeps quantity 1 and stays in the basket, total 13.98¤', async () => {
    await basket.minusButton(productA.name).click();
    await basket.expectRow(productA.name, 1);
    await basket.expectTotal('13.98¤');
  });

  await test.step('5. Click trash on A: no row for A, B stays with quantity 1, total 8.99¤, counter 1', async () => {
    await basket.removeButton(productA.name).click();
    await basket.expectNoRow(productA.name);
    await basket.expectRow(productB.name, 1);
    await basket.expectTotal('8.99¤');
    await search.expectBasketCounter(1);
  });
});
"}

{"file_path":"/Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/set-3/run-2/suite-a/tests/TC-04-purchase-limit.spec.ts","content":"// TC-04: Purchase limit for one product (test-cases/TC-04-purchase-limit.md)
import { test, expect } from '../fixtures';
import { BasketPage } from '../pages/basket-page';
import { SearchPage } from '../pages/search-page';
import { PRODUCTS, PURCHASE_LIMIT } from '../helpers/data';
import { newCustomer, registerAndLogin } from '../helpers/customer';

test('TC-04: purchase limit for one product', async ({ page }) => {
  const product = PRODUCTS.appleJuice;
  const limitMessage = `You can order only up to ${PURCHASE_LIMIT} items of this product.`;
  const search = new SearchPage(page);
  const basket = new BasketPage(page);
  await registerAndLogin(page, newCustomer('TC04'));

  await test.step('1. Add the product from the product list: message and counter 1', async () => {
    await search.goto();
    await search.addToBasket(product.name);
    await search.expectNotification(`Placed ${product.name} into basket.`);
    await search.expectBasketCounter(1);
  });

  await test.step('2. Click plus until the quantity is 5: no error, total 9.95¤', async () => {
    await basket.goto();
    for (let quantity = 2; quantity <= PURCHASE_LIMIT; quantity++) {
      await basket.plusButton(product.name).click();
      await basket.expectRow(product.name, quantity);
    }
    await basket.expectTotal('9.95¤');
    await expect(page.getByText(limitMessage)).toHaveCount(0);
  });

  await test.step('3. Click plus once more: the limit error shows', async () => {
    await basket.plusButton(product.name).click();
    await search.expectNotification(limitMessage);
  });

  await test.step('4. The product keeps quantity 5, total 9.95¤, counter 5', async () => {
    await basket.expectRow(product.name, PURCHASE_LIMIT);
    await basket.expectTotal('9.95¤');
    await search.expectBasketCounter(PURCHASE_LIMIT);
  });

  await test.step('5. Add the product again from the product list: the limit error shows, counter 5', async () => {
    await search.goto();
    await search.addToBasket(product.name);
    await search.expectNotification(limitMessage);
    await search.expectBasketCounter(PURCHASE_LIMIT);
  });
});
"}

{"file_path":"/Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/set-3/run-2/suite-a/tests/TC-05-valid-coupon.spec.ts","content":"// TC-05: Valid coupon on the payment step (test-cases/TC-05-valid-coupon.md)
import { test, expect } from '../fixtures';
import { BasketPage } from '../pages/basket-page';
import { SearchPage } from '../pages/search-page';
import { AddressSelectPage, DeliveryPage, OrderSummaryPage, PaymentPage } from '../pages/checkout-pages';
import { DELIVERY, PRODUCTS, SAVED_CARD } from '../helpers/data';
import { currentMonthCoupon } from '../helpers/coupon';
import { newCustomer, registerAndLogin, saveAddress, saveCard } from '../helpers/customer';

test('TC-05: valid coupon on the payment step', async ({ page }) => {
  const product = PRODUCTS.eggfruitJuice;
  const search = new SearchPage(page);
  const basket = new BasketPage(page);
  const addresses = new AddressSelectPage(page);
  const delivery = new DeliveryPage(page);
  const payment = new PaymentPage(page);
  const summary = new OrderSummaryPage(page);

  await registerAndLogin(page, newCustomer('TC05'));
  await saveAddress(page);
  await saveCard(page);

  // Precondition: the basket holds the product with quantity 2.
  await search.goto();
  await search.addToBasket(product.name);
  await search.addToBasket(product.name);
  await search.expectBasketCounter(2);

  await test.step('1. Open the basket, click Checkout: the saved address is shown', async () => {
    await basket.goto();
    await basket.checkout();
    await expect(page.getByRole('heading', { name: 'Select an address' })).toBeVisible();
    await expect(page.getByRole('row').filter({ hasText: '1 Khreshchatyk Street' })).toBeVisible();
  });

  await test.step('2. Select the saved address, click Continue: the delivery speeds are shown', async () => {
    await addresses.selectSavedAddress();
    await addresses.continue();
    await delivery.expectSpeeds();
    await expect(delivery.speedRow(DELIVERY.oneDay)).toContainText('0.99¤');
    await expect(delivery.speedRow('Fast Delivery')).toContainText('0.50¤');
    await expect(delivery.speedRow(DELIVERY.standard)).toContainText('0.00¤');
  });

  await test.step('3. Select One Day Delivery, click Continue: the saved card and the coupon panel are shown', async () => {
    await delivery.selectSpeed(DELIVERY.oneDay);
    await delivery.continue();
    await payment.expectOpen();
    await expect(page.getByRole('row').filter({ hasText: SAVED_CARD.lastFour })).toBeVisible();
    await expect(payment.couponButton).toBeVisible();
  });

  await test.step('4. Open the coupon panel, redeem the coupon of this month: the discount message shows', async () => {
    await payment.openCouponPanel();
    await payment.redeemCoupon(currentMonthCoupon());
    await search.expectNotification('Your discount of 10% will be applied during checkout.');
  });

  await test.step('5. Select the saved card, click Continue: the order summary shows the 10% promotion', async () => {
    await payment.selectSavedCard();
    await payment.continue();
    await summary.expectOpen();
    await expect(summary.summaryValue('Items')).toHaveText('17.98¤');
    await expect(summary.summaryValue('Delivery')).toHaveText('0.99¤');
    await expect(summary.summaryValue('Promotion')).toHaveText('1.80¤');
    await expect(summary.summaryValue('Total Price')).toHaveText('17.17¤');
  });
});
