{"file_path":"/Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/set-3/run-2/suite-a/tests/TC-07-card-order-end-to-end.spec.ts","content":"// TC-07: Order with a card, from basket to order history (test-cases/TC-07-card-order-end-to-end.md)
import { test, expect } from '../fixtures';
import { BasketPage } from '../pages/basket-page';
import { SearchPage } from '../pages/search-page';
import { OrderHistoryPage } from '../pages/account-pages';
import {
  AddressSelectPage,
  DeliveryPage,
  OrderCompletionPage,
  OrderSummaryPage,
  PaymentPage,
} from '../pages/checkout-pages';
import { DELIVERY, PRODUCTS, SAVED_ADDRESS, SAVED_CARD } from '../helpers/data';
import { currentMonthCoupon } from '../helpers/coupon';
import { newCustomer, registerAndLogin, saveAddress, saveCard } from '../helpers/customer';

test('TC-07: order with a card, from basket to order history', async ({ page }) => {
  const productA = PRODUCTS.eggfruitJuice;
  const productB = PRODUCTS.carrotJuice;
  const search = new SearchPage(page);
  const basket = new BasketPage(page);
  const addresses = new AddressSelectPage(page);
  const delivery = new DeliveryPage(page);
  const payment = new PaymentPage(page);
  const summary = new OrderSummaryPage(page);
  const completion = new OrderCompletionPage(page);
  const history = new OrderHistoryPage(page);

  await registerAndLogin(page, newCustomer('TC07'));
  await saveAddress(page);
  await saveCard(page);

  await test.step('1. Add product A two times and product B one time: the basket counter shows 3', async () => {
    await search.goto();
    await search.addToBasket(productA.name);
    await search.addToBasket(productA.name);
    await search.addToBasket(productB.name);
    await search.expectBasketCounter(3);
  });

  await test.step('2. Open the basket: A with quantity 2, B with quantity 1, total 20.97¤', async () => {
    await basket.goto();
    await basket.expectRow(productA.name, 2);
    await basket.expectRow(productB.name, 1);
    await basket.expectTotal('20.97¤');
  });

  await test.step('3. Click Checkout, select the saved address, Continue: the delivery page opens', async () => {
    await basket.checkout();
    await addresses.selectSavedAddress();
    await addresses.continue();
    await delivery.expectSpeeds();
  });

  await test.step('4. Select One Day Delivery, Continue: the payment page opens', async () => {
    await delivery.selectSpeed(DELIVERY.oneDay);
    await delivery.continue();
    await payment.expectOpen();
  });

  await test.step('5. Redeem the coupon of this month: the discount message shows', async () => {
    await payment.openCouponPanel();
    await payment.redeemCoupon(currentMonthCoupon());
    await search.expectNotification('Your discount of 10% will be applied during checkout.');
  });

  await test.step('6. Select the saved card, Continue: the summary shows address, card and totals', async () => {
    await payment.selectSavedCard();
    await payment.continue();
    await summary.expectOpen();
    await expect(page.getByText(SAVED_ADDRESS.address)).toBeVisible();
    await expect(page.getByText(`ending in ${SAVED_CARD.lastFour}`)).toBeVisible();
    await expect(summary.summaryValue('Items')).toHaveText('20.97¤');
    await expect(summary.summaryValue('Delivery')).toHaveText('0.99¤');
    await expect(summary.summaryValue('Promotion')).toHaveText('2.10¤');
    await expect(summary.summaryValue('Total Price')).toHaveText('19.86¤');
  });

  let orderId = '';

  await test.step('7. Click Place your order and pay: the confirmation page with the order ID opens', async () => {
    await summary.placeOrder();
    await expect(page).toHaveURL(/#\/order-completion\/.+/);
    await expect(page.getByText('Thank you for your purchase!')).toBeVisible();
    orderId = completion.orderId();
  });

  await test.step('8. The confirmation page shows A with quantity 2, B with quantity 1 and the totals', async () => {
    await expect(page.getByRole('row').filter({ hasText: productA.name })).toContainText('2');
    await expect(page.getByRole('row').filter({ hasText: productB.name })).toContainText('1');
    await expect(completion.summaryValue('Items')).toHaveText('20.97¤');
    await expect(completion.summaryValue('Delivery')).toHaveText('0.99¤');
    await expect(completion.summaryValue('Promotion')).toHaveText('2.10¤');
    await expect(completion.summaryValue('Total Price')).toHaveText('19.86¤');
  });

  await test.step('9. The basket counter shows 0, the basket is empty and Checkout is disabled', async () => {
    await search.expectBasketCounter(0);
    await basket.goto();
    await expect(basket.row(productA.name)).toHaveCount(0);
    await expect(basket.row(productB.name)).toHaveCount(0);
    await expect(basket.checkoutButton).toBeDisabled();
  });

  await test.step('10. Order History shows the order with its ID, total 19.86¤, A with 2 and B with 1', async () => {
    await page.goto('/#/order-history');
    await history.openAccountMenu().catch(() => undefined);
    await history.closeMenu().catch(() => undefined);
    await history.goto();
    const order = history.orderSection(orderId);
    await expect(order).toContainText(orderId);
    await expect(order).toContainText('19.86¤');
    await expect(order).toContainText(productA.name);
    await expect(order).toContainText(productB.name);
  });
});
"}

{"file_path":"/Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/set-3/run-2/suite-a/tests/TC-08-wallet-payment.spec.ts","content":"// TC-08: Payment with the wallet (test-cases/TC-08-wallet-payment.md)
import { test, expect } from '../fixtures';
import { BasketPage } from '../pages/basket-page';
import { SearchPage } from '../pages/search-page';
import { OrderHistoryPage, WalletPage } from '../pages/account-pages';
import { AddressSelectPage, DeliveryPage, OrderSummaryPage, PaymentPage } from '../pages/checkout-pages';
import { DELIVERY, PRODUCTS } from '../helpers/data';
import { newCustomer, registerAndLogin, saveAddress, saveCard, addWalletMoney } from '../helpers/customer';

test('TC-08: payment with the wallet', async ({ page }) => {
  const product = PRODUCTS.eggfruitJuice;
  const search = new SearchPage(page);
  const basket = new BasketPage(page);
  const addresses = new AddressSelectPage(page);
  const delivery = new DeliveryPage(page);
  const payment = new PaymentPage(page);
  const summary = new OrderSummaryPage(page);
  const wallet = new WalletPage(page);
  const history = new OrderHistoryPage(page);

  await registerAndLogin(page, newCustomer('TC08'));
  await saveAddress(page);
  await saveCard(page);

  // Precondition 4: the basket holds the product with quantity 1.
  await search.goto();
  await search.addToBasket(product.name);
  await search.expectBasketCounter(1);

  // Precondition 5: the wallet balance is 5.00. The shop adds the money with the saved card.
  expect(await addWalletMoney(page, 5)).toBe(5);

  // Part 1: the wallet holds less than the order total.
  await test.step('1. Open the basket, Checkout, select the address, Continue: the delivery page opens', async () => {
    await basket.goto();
    await basket.checkout();
    await addresses.selectSavedAddress();
    await addresses.continue();
    await delivery.expectSpeeds();
  });

  await test.step('2. Select Standard Delivery, Continue: the wallet balance 5.00 and the button Pay 8.99¤ are shown', async () => {
    await delivery.selectSpeed(DELIVERY.standard);
    await delivery.continue();
    await payment.expectOpen();
    await expect(page.getByText(/Pay using wallet/)).toContainText('5.00');
    await expect(payment.walletPayButton('8.99¤')).toBeVisible();
  });

  await test.step('3. The button Pay 8.99¤ is disabled', async () => {
    await expect(payment.walletPayButton('8.99¤')).toBeDisabled();
  });

  await test.step('4. Order History shows that no order is placed yet', async () => {
    await history.openAccountMenu();
    await history.clickMenuItem('Orders & Payment');
    await history.clickMenuItem('Order History');
    await expect(page.getByText('You have not placed any orders yet.')).toBeVisible();
  });

  await test.step('5. Digital Wallet shows the balance 5.00', async () => {
    await page.getByRole('button', { name: 'Show/hide account menu' }).click();
    await history.clickMenuItem('Orders & Payment');
    await history.clickMenuItem('Digital Wallet');
    await wallet.expectBalance('5.00');
  });

  // Part 2: the wallet holds exactly the order total.
  await test.step('6. Add 3.99 to the wallet with the saved card: the balance 8.99 and the enabled Pay 8.99¤ button', async () => {
    expect(await addWalletMoney(page, 3.99)).toBeCloseTo(8.99, 2);
    await basket.goto();
    await basket.checkout();
    await addresses.selectSavedAddress();
    await addresses.continue();
    await delivery.selectSpeed(DELIVERY.standard);
    await delivery.continue();
    await payment.expectOpen();
    await expect(page.getByText(/Pay using wallet/)).toContainText('8.99');
    await expect(payment.walletPayButton('8.99¤')).toBeEnabled();
  });

  await test.step('7. Click Pay 8.99¤: the order summary shows Digital Wallet and Total Price 8.99¤', async () => {
    await payment.selectWallet('8.99¤');
    await summary.expectOpen();
    await expect(page.getByText('Digital Wallet')).toBeVisible();
    await expect(summary.summaryValue('Total Price')).toHaveText('8.99¤');
  });

  await test.step('8. Click Place your order and pay: the confirmation page shows the thank you text', async () => {
    await summary.placeOrder();
