import { BasePage } from '@/page-objects/base-page';
import { expectCount, expectText, expectUrlMatches, expectVisible } from '@/utils/assertions/ui-assertions';
import type { ProductInfo } from '@/utils/types/product';

const EMPTY_HISTORY_MESSAGE = 'You have not placed any orders yet.';
const ORDER_ID_LABEL = 'Order ID';
const TOTAL_PRICE_LABEL = 'Total Price';
const BONUS_LABEL = 'Bonus';
const QUANTITY_CELL_INDEX = 2;

// Each order: a header with the label and value pairs (ID, Total Price, Bonus), then a table of its lines.
export class OrderHistoryPage extends BasePage {
  constructor(page: Page) {
    super(page);
  }

  async shouldSeePage(): Promise<void> {
    await expectUrlMatches(this.page, /#\/order-history$/, 'The order history page is open');
  }

  async shouldSeeNoOrders(): Promise<void> {
    await expectVisible(this.page.getByText(EMPTY_HISTORY_MESSAGE), `The page shows "${EMPTY_HISTORY_MESSAGE}"`);
  }

  async shouldSeeOrderCount(count: number): Promise<void> {
    await expectCount(this.page.getByText(ORDER_ID_LABEL, { exact: true }), count, `The page shows ${count} order(s)`);
  }

  async shouldSeeOrder(orderId: string, totalPrice: string): Promise<void> {
    const header = this.orderHeader(orderId);
    await expectVisible(header, `The page shows the order ${orderId}`);
    await expectVisible(this.labelValue(header, TOTAL_PRICE_LABEL, totalPrice), `Order ${orderId} shows the total ${totalPrice}`);
  }

  async shouldSeeOrderBonus(orderId: string, bonus: number): Promise<void> {
    await expectVisible(
      this.labelValue(this.orderHeader(orderId), BONUS_LABEL, String(bonus)),
      `Order ${orderId} shows the bonus ${bonus}`,
    );
  }

  async shouldSeeOrderLine(orderId: string, product: ProductInfo, quantity: number): Promise<void> {
    const row = this.orderBlock(orderId).getByRole('row').filter({ hasText: product.name });
    await expectVisible(row, `Order ${orderId} shows "${product.name}"`);
    await expectText(row.getByRole('cell').nth(QUANTITY_CELL_INDEX), String(quantity), `"${product.name}" has quantity ${quantity}`);
  }

  // The header is the parent of the element that shows the order ID.
  private orderHeader(orderId: string): Locator {
    return this.page.getByText(`#${orderId}`, { exact: true }).locator('xpath=../..');
  }

  private orderBlock(orderId: string): Locator {
    return this.orderHeader(orderId).locator('xpath=..');
  }

  // A pair of a label and its value sits in one element: "Total Price 19.86¤".
  private labelValue(header: Locator, label: string, value: string): Locator {
    return header.locator('div').filter({ hasText: new RegExp(`^${escapeRegex(label)}\\s*${escapeRegex(value)}$`) });
  }
}

const escapeRegex = (text: string): string => text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
"}

